package com.portfolio.fraud.dto; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; public final class TransactionDtos { private TransactionDtos(){} public record MoneyRequest(@NotNull Long accountId,@NotNull @DecimalMin(value="0.01") @Digits(integer=17,fraction=2) BigDecimal amount,@Size(max=255) String description){} public record TransferRequest(@NotNull Long senderAccountId,@NotNull Long recipientAccountId,@NotNull @DecimalMin(value="0.01") @Digits(integer=17,fraction=2) BigDecimal amount,@Size(max=255) String description){} public record CreateAccountRequest(@NotBlank @Pattern(regexp="CHECKING|SAVINGS") String accountType,@NotBlank @Pattern(regexp="[A-Z]{3}") String currency,@NotNull @DecimalMin(value="0.00") @Digits(integer=17,fraction=2) BigDecimal initialBalance){} public record AccountResponse(Long id,String accountNumber,String accountType,BigDecimal balance,String currency,String status){} public record TransactionResponse(Long id,String type,BigDecimal amount,String status,String riskLevel,int riskScore,String description,Instant createdAt,Long senderAccountId,Long recipientAccountId,String currency){} }
